// Generated by ChatGPT

import SwiftUI
import Supabase
import PhotosUI
import UIKit

struct ProfileView: View {

    @ObservedObject var viewModel: DashboardViewModel
    @ObservedObject var connectAccount: Account

    // Use the same GamificationViewModel as Dashboard
    @ObservedObject var gamificationViewModel: GamificationViewModel

    // MARK: - View State

    @State private var isLoadingFeaturedAchievements = true
    
    
    // MARK: - Custom Profile Photo

    @State private var selectedPhoto: PhotosPickerItem?

    @State private var customProfileImage: UIImage?

    @State private var showCamera = false

    @State private var showPhotoError = false

    @State private var photoErrorMessage = ""

    @State private var avatarSource: AvatarSource = .cosmetic

    private enum AvatarSource {
        case cosmetic
        case custom
        case defaultAvatar
    }


    var body: some View {

        Form {

            // ---------------------------------
            // MARK: - Profile Header
            // ---------------------------------

            Section {

                VStack(spacing: 12) {
                    
                     
                    // MARK: - Change Profile Picture

                    HStack(spacing: 12) {

                        PhotosPicker(
                            selection: $selectedPhoto,
                            matching: .images
                        ) {

                            Label(
                                "Choose Photo",
                                systemImage: "photo.on.rectangle"
                            )
                        }
                        .buttonStyle(.bordered)

                        Button {

                            if UIImagePickerController
                                .isSourceTypeAvailable(.camera) {

                                showCamera = true

                            } else {

                                photoErrorMessage =
                                    "Camera is not available on this device."

                                showPhotoError = true
                            }

                        } label: {

                            Label(
                                "Take Photo",
                                systemImage: "camera"
                            )
                        }
                        .buttonStyle(.bordered)
                    }

                    Button("Use Cosmetic Avatar") {
                        avatarSource = .cosmetic
                    }
                    .font(.caption)

                    Button("Use Default Avatar") {
                        avatarSource = .defaultAvatar
                    }
                    .font(.caption)

                    // MARK: - Equipped Avatar and Frame

                    profileCosmeticPreview

                    if let avatar = equippedAvatar {

                        Text(avatar.name)
                            .font(.caption)
                            .foregroundColor(.secondary)
                    }

                    if let frame = equippedFrame {

                        Text("\(frame.name) Equipped")
                            .font(.caption2)
                            .foregroundColor(.secondary)
                    }


                    Text(viewModel.username)
                        .font(.title2)
                        .fontWeight(.bold)

                    Text(userEmail)
                        .font(.subheadline)
                        .foregroundColor(.secondary)

                }
                .frame(maxWidth: .infinity)
                .padding(.vertical, 12)
            }


            // ---------------------------------
            // MARK: - Featured Achievements
            // ---------------------------------

            Section("Featured Achievements") {

                if isLoadingFeaturedAchievements {

                    ProgressView("Loading featured achievements...")

                } else if gamificationViewModel.featuredAchievements.isEmpty {

                    Text("No featured achievements selected yet.")
                        .font(.subheadline)
                        .foregroundColor(.secondary)

                } else {

                    // Display saved badges in their selected order
                    ForEach(
                        gamificationViewModel.featuredAchievements
                    ) { featured in

                        if let achievement =
                            gamificationViewModel.achievements.first(
                                where: {
                                    $0.id == featured.achievement_id
                                }
                            ) {

                            HStack(spacing: 12) {

                                Image(
                                    systemName: achievement.icon_name
                                )
                                .font(.title2)
                                .foregroundColor(
                                    tierColor(for: achievement.tier)
                                )
                                .frame(width: 40)

                                VStack(
                                    alignment: .leading,
                                    spacing: 4
                                ) {

                                    Text(achievement.title)
                                        .font(.headline)

                                    Text(
                                        achievement.tier.capitalized
                                    )
                                    .font(.caption)
                                    .foregroundColor(
                                        tierColor(for: achievement.tier)
                                    )
                                }

                                Spacer()

                                Image(systemName: "checkmark.seal.fill")
                                    .foregroundColor(
                                        tierColor(for: achievement.tier)
                                    )
                            }
                            .padding(.vertical, 6)

                        } else {

                            Text("Featured achievement unavailable")
                                .foregroundColor(.secondary)
                        }
                    }
                }


                // MARK: - Manage Featured Achievements

                NavigationLink {

                    FeaturedAchievementsSelectionView(
                        gamificationViewModel: gamificationViewModel
                    )

                } label: {

                    Label(
                        "Choose Featured Achievements",
                        systemImage: "medal.fill"
                    )
                }
                
                // MARK: - View All Achievements

                NavigationLink {

                    AchievementsView(
                        gamificationViewModel: gamificationViewModel
                    )

                } label: {

                    Label(
                        "View All Achievements",
                        systemImage: "trophy.fill"
                    )
                }

            }


            // ---------------------------------
            // MARK: - Personal Information
            // ---------------------------------

            Section("Personal Information") {

                HStack {

                    Text("Age")

                    Spacer()

                    Text(ageText)
                        .foregroundColor(.secondary)
                }

                HStack {

                    Text("Height")

                    Spacer()

                    Text(viewModel.formatHeight)
                        .foregroundColor(.secondary)
                }

                HStack {

                    Text("Current Weight")

                    Spacer()

                    Text(weightText)
                        .foregroundColor(.secondary)
                }
            }


            // ---------------------------------
            // MARK: - Account
            // ---------------------------------

            Section("Account") {

                Label(
                    "Health Data Sources",
                    systemImage: "heart.text.square"
                )

                Label(
                    "Settings",
                    systemImage: "gearshape"
                )
            }


            // ---------------------------------
            // MARK: - Sign Out
            // ---------------------------------

            Section {

                Button(role: .destructive) {

                    Task {

                        await connectAccount.signOutUser()
                    }

                } label: {

                    HStack {

                        Spacer()

                        Text("Sign Out")

                        Spacer()
                    }
                }
            }

        } // Closes Form

        // Show the themed background behind the Form
                .scrollContentBackground(.hidden)

                // Apply the equipped app theme
                .modifier(
                    ProjectHealthThemeModifier(
                        gamificationViewModel: gamificationViewModel
                    )
                )
        
        .navigationTitle("Profile")
        .navigationBarTitleDisplayMode(.inline)

        
        // ---------------------------------
        // MARK: - Load Profile Data
        // ---------------------------------

        .task {

            isLoadingFeaturedAchievements = true

            // Load all achievements and unlock statuses
            await gamificationViewModel.refreshAchievementProgress()

            // Load the player's selected badges
            await gamificationViewModel.refreshFeaturedAchievements()

            isLoadingFeaturedAchievements = false

            // NEW: Load equipped avatar and profile frame
            await gamificationViewModel.refreshCosmeticData()
        }
        
        
        // MARK: - Handle Selected Photo

        .onChange(of: selectedPhoto) { _, newPhoto in

            guard let newPhoto else {
                return
            }

            Task {

                do {

                    guard let imageData = try await
                        newPhoto.loadTransferable(type: Data.self),

                        let image = UIImage(data: imageData) else {

                        photoErrorMessage =
                            "Unable to load the selected photo."

                        showPhotoError = true
                        return
                    }

                    customProfileImage = image
                    avatarSource = .custom

                } catch {

                    photoErrorMessage = error.localizedDescription
                    showPhotoError = true
                }
            }
        }


        // MARK: - Camera Sheet

        .sheet(isPresented: $showCamera) {

            ProfileCameraPicker { image in

                customProfileImage = image
                avatarSource = .custom
            }
        }


        // MARK: - Photo Error Alert

        .alert(
            "Photo Unavailable",
            isPresented: $showPhotoError
        ) {

            Button("OK", role: .cancel) {}

        } message: {

            Text(photoErrorMessage)
        }



    } // Closes body


    // ---------------------------------
    // MARK: - Achievement Tier Colors
    // ---------------------------------

    private func tierColor(for tier: String) -> Color {

        switch tier {

        case "bronze":
            return .brown

        case "silver":
            return .gray

        case "gold":
            return .yellow

        default:
            return .secondary
        }
    }

    
    // MARK: - Equipped Avatar

    private var equippedAvatar: CosmeticDefinition? {

        guard let avatarID =
            gamificationViewModel.equippedCosmeticID(for: "avatar") else {

            return nil
        }

        return gamificationViewModel.cosmeticCatalog.first {
            $0.id == avatarID
        }
    }


    // MARK: - Equipped Profile Frame

    private var equippedFrame: CosmeticDefinition? {

        guard let frameID =
            gamificationViewModel.equippedCosmeticID(for: "frame") else {

            return nil
        }

        return gamificationViewModel.cosmeticCatalog.first {
            $0.id == frameID
        }
    }


    
    
    // MARK: - Cosmetic Profile Preview

    private var profileCosmeticPreview: some View {

        ZStack {

            Circle()
                .fill(Color(.secondarySystemGroupedBackground))
                .frame(width: 88, height: 88)

            // MARK: - Custom Profile Photo

            if avatarSource == .custom,
               let customProfileImage {

                Image(uiImage: customProfileImage)
                    .resizable()
                    .scaledToFill()
                    .frame(width: 88, height: 88)
                    .clipShape(Circle())

            // MARK: - Equipped Cosmetic Avatar

            } else if avatarSource == .cosmetic,
                      let avatar = equippedAvatar {

                Image(avatar.asset_key)
                    .resizable()
                    .scaledToFill()
                    .frame(width: 88, height: 88)
                    .clipShape(Circle())

            // MARK: - Default Avatar

            } else {

                Image(systemName: "person.circle.fill")
                    .resizable()
                    .scaledToFit()
                    .frame(width: 78, height: 78)
                    .foregroundColor(.secondary)
            }

            // MARK: - Equipped Profile Frame

            if let frame = equippedFrame {

                Image(frame.asset_key)
                    .resizable()
                    .scaledToFit()
                    .frame(width: 112, height: 112)
                    .accessibilityHidden(true)
            }

        }
        .frame(width: 112, height: 112)
    }


    // MARK: - Cosmetic Collection Colors

    private func cosmeticColor(
        for collection: String
    ) -> Color {

        switch collection {

        case "astral":
            return .purple

        case "nature":
            return .green

        case "cyber":
            return .cyan

        default:
            return .secondary
        }
    }


    // ---------------------------------
    // MARK: - Email
    // ---------------------------------

    private var userEmail: String {

        supabase.auth.currentUser?.email
            ?? "No email available"
    }


    // ---------------------------------
    // MARK: - Age
    // ---------------------------------

    private var ageText: String {

        guard let age = viewModel.age else {
            return "--"
        }

        return "\(age)"
    }


    // ---------------------------------
    // MARK: - Weight
    // ---------------------------------

    private var weightText: String {

        guard let weight = viewModel.currentWeight else {
            return "--"
        }

        return "\(weight.formatted()) lbs"
    }

} // Closes ProfileView
